<script setup lang="ts">
import {onMounted,ref} from 'vue';import api from '../api';
const rows=ref<any[]>([]),file=ref<File|null>(null),message=ref(''),busy=ref(false);
async function load(){rows.value=(await api.get('/documents')).data.data}
function pick(e:Event){const target=e.target as HTMLInputElement;file.value=target.files?.[0]||null}
async function upload(){if(!file.value)return;busy.value=true;message.value='';try{const body=new FormData();body.append('file',file.value);await api.post('/documents',body,{headers:{'Content-Type':'multipart/form-data'}});file.value=null;message.value='Documento enviado com sucesso.';await load()}catch{message.value='Falha no envio. Use PDF, DOC, DOCX, JPG ou PNG (até 10 MB).'}finally{busy.value=false}}
async function download(doc:any){const response=await api.get(`/documents/${doc.id}/download`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=doc.original_name;a.click();URL.revokeObjectURL(url)}
async function remove(doc:any){if(confirm('Excluir este documento?')){await api.delete(`/documents/${doc.id}`);await load()}}
onMounted(load);
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">ARQUIVO DIGITAL</p><h1>Documentos</h1><p class="muted">Armazene arquivos fictícios vinculados ao workspace.</p></div></div><div class="panel form-panel"><h2>Enviar documento</h2><form class="inline-form" @submit.prevent="upload"><label class="wide">Arquivo (PDF, DOC, DOCX, JPG ou PNG)<input type="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png" required @change="pick"/></label><button class="primary" :disabled="busy||!file">{{busy?'Enviando...':'Enviar arquivo'}}</button></form><p v-if="message" class="muted">{{message}}</p><p class="footnote">Limite: 10 MB por arquivo. Os arquivos ficam em armazenamento privado no backend.</p></div><div class="panel"><div class="panel-heading"><h2>Documentos enviados</h2></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Tipo</th><th>Tamanho</th><th>Enviado em</th><th></th></tr></thead><tbody><tr v-for="d in rows" :key="d.id"><td><b>{{d.original_name}}</b></td><td>{{d.mime_type||'—'}}</td><td>{{(d.size/1024).toFixed(1)}} KB</td><td>{{new Date(d.created_at).toLocaleDateString('pt-BR')}}</td><td><button class="secondary" @click="download(d)">Baixar</button> <button class="danger-link" @click="remove(d)">Excluir</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty">Nenhum documento enviado.</p></div></section></template>
